   } else if (strcmp(thd->security_context()->priv_user().str,
                     for_user->user.str) != 0) {
@@ -2064,8 +2064,7 @@ bool Sql_cmd_show_grants::execute(THD *thd) {
     }
   }
   List_of_auth_id_refs authid_list;
-  if (using_users != 0 && using_users->elements > 0) {
