diff --git a/mysql-test/suite/auth_sec/r/mandatory_roles_bugs.result b/mysql-test/suite/auth_sec/r/mandatory_roles_bugs.result
new file mode 100644
index 000000000000..7627b20934cf
--- /dev/null
+++ b/mysql-test/suite/auth_sec/r/mandatory_roles_bugs.result
@@ -0,0 +1,33 @@
+#
+# Bug #28699403: SHOW GRANTS THROW ERROR FOR EXISTING SESSION WHEN
+#  MANDATORY_ROLES CHANGED
+CREATE USER u1@localhost;
+CREATE ROLE r1;
+CREATE TABLE t1 (a INT);
+GRANT ALL ON t1 TO r1;
+SET GLOBAL mandatory_roles="r1";
+SET GLOBAL activate_all_roles_on_login = 'ON';
+# in connection con1
+SHOW GRANTS;
+Grants for u1@localhost
+GRANT USAGE ON *.* TO `u1`@`localhost`
+GRANT ALL PRIVILEGES ON `test`.`t1` TO `u1`@`localhost`
+GRANT `r1`@`%` TO `u1`@`localhost`
+SELECT a FROM t1;
+a
+# in connection default
+SET GLOBAL mandatory_roles="";
+# in connection con1
+# test: Must not fail
+SHOW GRANTS;
+Grants for u1@localhost
+GRANT USAGE ON *.* TO `u1`@`localhost`
+SELECT * FROM t1;
+ERROR 42000: SELECT command denied to user 'u1'@'localhost' for table 't1'
+# in connection default
+DROP USER u1@localhost;
+DROP ROLE r1;
+DROP TABLE t1;
+SET GLOBAL mandatory_roles=DEFAULT;
+SET GLOBAL activate_all_roles_on_login=DEFAULT;
+# End of 8.0 tests
diff --git a/mysql-test/suite/auth_sec/t/mandatory_roles_bugs.test b/mysql-test/suite/auth_sec/t/mandatory_roles_bugs.test
new file mode 100644
index 000000000000..05fab893ebe7
--- /dev/null
+++ b/mysql-test/suite/auth_sec/t/mandatory_roles_bugs.test
@@ -0,0 +1,43 @@
+--echo #
+--echo # Bug #28699403: SHOW GRANTS THROW ERROR FOR EXISTING SESSION WHEN
+--echo #  MANDATORY_ROLES CHANGED
+
+# Save the initial number of concurrent sessions
+--source include/count_sessions.inc
+
+CREATE USER u1@localhost;
+CREATE ROLE r1;
+CREATE TABLE t1 (a INT);
+GRANT ALL ON t1 TO r1;
+SET GLOBAL mandatory_roles="r1";
+SET GLOBAL activate_all_roles_on_login = 'ON';
+
+connect(con1,localhost,u1,,test);
+connection con1;
+--echo # in connection con1
+SHOW GRANTS;
+SELECT a FROM t1;
+connection default;
+--echo # in connection default
+SET GLOBAL mandatory_roles="";
+connection con1;
+--echo # in connection con1
+--echo # test: Must not fail
+SHOW GRANTS;
+--error ER_TABLEACCESS_DENIED_ERROR
+SELECT * FROM t1;
+
+connection default;
+--echo # in connection default
+
+disconnect con1;
+DROP USER u1@localhost;
+DROP ROLE r1;
+DROP TABLE t1;
+SET GLOBAL mandatory_roles=DEFAULT;
+SET GLOBAL activate_all_roles_on_login=DEFAULT;
+# Wait till all disconnects are completed
+--source include/wait_until_count_sessions.inc
+
+
+--echo # End of 8.0 tests
